// Profile parser + pad mapper on the compiled gta5 profile
// (firmware/test/fixtures/gta5.bpprofile, generated by `bodyctl profile compile`).
#include <unity.h>

#include <stdio.h>
#include <string.h>

#include <vector>

#include "padmap.h"
#include "param_table.h"
#include "profile_bin.h"
#include "protocol.h"

using namespace bp;

static std::vector<uint8_t> read_fixture(const char* name) {
  std::vector<uint8_t> out;
  for (const char* dir : {"test/fixtures/", "firmware/test/fixtures/"}) {
    char path[256];
    snprintf(path, sizeof(path), "%s%s", dir, name);
    FILE* f = fopen(path, "rb");
    if (!f) continue;
    uint8_t buf[2048];
    size_t n = fread(buf, 1, sizeof(buf), f);
    fclose(f);
    out.assign(buf, buf + n);
    return out;
  }
  TEST_FAIL_MESSAGE("fixture not found");
  return out;
}

static ProfileBin gta5() {
  std::vector<uint8_t> data = read_fixture("gta5.bpprofile");
  ProfileBin p;
  const char* err = nullptr;
  TEST_ASSERT_TRUE_MESSAGE(p.parse(data.data(), data.size(), &err), err);
  return p;
}

struct FakeState : BodyState {
  float run = 0, lean = 0, twist = 0;
  bool aiming = false, stopped = true, sprinting = false;
  float source(uint8_t s) const override {
    switch (s) {
      case SRC_RUN_CADENCE: return run;
      case SRC_LEAN: return lean;
      case SRC_TWIST: return twist;
      default: return 0;
    }
  }
  bool condition(uint8_t c) const override {
    switch (c) {
      case COND_AIMING: return aiming;
      case COND_STOPPED: return stopped;
      case COND_SPRINTING: return sprinting;
      default: return false;
    }
  }
};

static PadMapper mapper() {
  PadMapper m;
  m.set_profile(gta5());
  return m;
}

static constexpr uint32_t MS = 1000;

void setUp() {}
void tearDown() {}

void test_parse_gta5() {
  ProfileBin p = gta5();
  TEST_ASSERT_EQUAL(30, p.hold_ms);
  TEST_ASSERT_EQUAL(30, p.release_ms);
  TEST_ASSERT_EQUAL(OUT_LEFT_STICK, p.ports[0].output);  // A-E1
  TEST_ASSERT_EQUAL(OUT_SQUARE, p.ports[2].output);      // A-E3
  TEST_ASSERT_EQUAL(PORT_TRIGGER, p.ports[5].type);      // B-E2
  TEST_ASSERT_EQUAL(OUT_R2, p.ports[5].output);
  // car covers bike and boat; heli covers plane.
  TEST_ASSERT_EQUAL_PTR(p.mode(MODE_CAR), p.mode(MODE_BOAT));
  TEST_ASSERT_EQUAL_PTR(p.mode(MODE_HELI), p.mode(MODE_PLANE));
  const Binding* jump = p.binding(MODE_ON_FOOT, 2);
  TEST_ASSERT_NOT_NULL(jump);
  TEST_ASSERT_EQUAL(BIND_EVENT, jump->kind);
  TEST_ASSERT_EQUAL(EV_JUMP, jump->a);
  TEST_ASSERT_NULL(p.binding(MODE_QTE, 2));  // unlisted = neutral
}

void test_params_apply_to_belt() {
  ProfileBin p = gta5();
  BeltParams bp_;
  bp_.jump.dip_g = 0;
  for (int i = 0; i < p.n_params; ++i) TEST_ASSERT_TRUE(belt_param_set(&bp_, p.params[i].id, p.params[i].value));
  TEST_ASSERT_FLOAT_WITHIN(1e-6, -0.30f, bp_.jump.dip_g);
  TEST_ASSERT_EQUAL(200, bp_.step.refractory_ms);
}

void test_rejects_corruption() {
  std::vector<uint8_t> data = read_fixture("gta5.bpprofile");
  ProfileBin p;
  const char* err = nullptr;
  data[20] ^= 1;
  TEST_ASSERT_FALSE(p.parse(data.data(), data.size(), &err));
  TEST_ASSERT_EQUAL_STRING("bad crc", err);
  TEST_ASSERT_FALSE(p.parse(data.data(), 5, &err));
}

void test_jump_press_lasts_30_ms() {
  PadMapper m = mapper();
  FakeState st;
  uint8_t ev[] = {EV_JUMP};
  bool crit = false;
  TEST_ASSERT_TRUE(m.apply(st, ev, 1, 0, &crit));
  TEST_ASSERT_TRUE(crit);
  TEST_ASSERT_TRUE(m.report().button(OUT_SQUARE));
  m.apply(st, nullptr, 0, 29 * MS, &crit);
  TEST_ASSERT_TRUE(m.report().button(OUT_SQUARE));
  m.apply(st, nullptr, 0, 30 * MS, &crit);
  TEST_ASSERT_FALSE(m.report().button(OUT_SQUARE));
}

void test_mash_respects_release_and_cap() {
  PadMapper m = mapper();
  FakeState st;
  uint8_t ev[] = {EV_JUMP};
  int rises = 0;
  bool prev = false;
  for (uint32_t t = 0; t < 1000; ++t) {
    m.apply(st, ev, t % 10 == 0 ? 1 : 0, t * MS, nullptr);
    bool cur = m.report().button(OUT_SQUARE);
    rises += cur && !prev;
    prev = cur;
  }
  TEST_ASSERT_INT_WITHIN(1, 16, rises);
}

void test_run_and_lean_drive_left_stick() {
  PadMapper m = mapper();
  FakeState st;
  st.run = 0.8f;
  st.lean = -0.3f;
  bool crit = false;
  m.apply(st, nullptr, 0, 0, &crit);
  TEST_ASSERT_TRUE(crit);  // stick left neutral: run start flashes the marker
  TEST_ASSERT_FLOAT_WITHIN(1e-6, 0.8f, m.report().ly);
  TEST_ASSERT_FLOAT_WITHIN(1e-6, -0.3f, m.report().lx);
  st.run = 0.9f;
  m.apply(st, nullptr, 0, 10 * MS, &crit);
  TEST_ASSERT_FALSE(crit);  // continuous changes don't
}

void test_sprint_taps_cross_only_when_sprinting() {
  PadMapper m = mapper();
  FakeState st;
  uint8_t ev[] = {EV_STEP};
  m.apply(st, ev, 1, 0, nullptr);
  TEST_ASSERT_FALSE(m.report().button(OUT_CROSS));
  st.sprinting = true;
  m.apply(st, ev, 1, 300 * MS, nullptr);
  TEST_ASSERT_TRUE(m.report().button(OUT_CROSS));
}

void test_aim_holds_l2_shoot_gated() {
  PadMapper m = mapper();
  FakeState st;
  uint8_t shoot[] = {EV_SHOOT};
  m.apply(st, shoot, 1, 0, nullptr);
  TEST_ASSERT_EQUAL_FLOAT(0, m.report().r2);  // not aiming: no shot (hard rule 7)
  st.aiming = true;
  m.apply(st, nullptr, 0, 40 * MS, nullptr);
  TEST_ASSERT_EQUAL_FLOAT(1, m.report().l2);
  m.apply(st, shoot, 1, 50 * MS, nullptr);
  TEST_ASSERT_EQUAL_FLOAT(1, m.report().r2);
}

void test_car_mode_neutral_sticks_and_throttle() {
  PadMapper m = mapper();
  FakeState st;
  st.run = 0.7f;
  st.lean = 0.5f;
  st.twist = 0.4f;
  m.apply(st, nullptr, 0, 0, nullptr);
  TEST_ASSERT_TRUE(m.set_mode(MODE_BIKE, 10 * MS));
  uint8_t ev[] = {EV_JUMP};
  m.apply(st, ev, 1, 20 * MS, nullptr);
  const PadReport& r = m.report();
  TEST_ASSERT_EQUAL_FLOAT(0, r.lx);
  TEST_ASSERT_EQUAL_FLOAT(0, r.ly);
  TEST_ASSERT_EQUAL_FLOAT(0, r.rx);  // hard rule 4
  TEST_ASSERT_FLOAT_WITHIN(1e-6, 0.7f, r.r2);
  TEST_ASSERT_FALSE(r.button(OUT_SQUARE));
}

void test_exit_vehicle_needs_stopped() {
  PadMapper m = mapper();
  FakeState st;
  st.stopped = false;
  m.set_mode(MODE_CAR, 0);
  uint8_t ev[] = {EV_ENTER_EXIT};
  m.apply(st, ev, 1, 10 * MS, nullptr);
  TEST_ASSERT_FALSE(m.report().button(OUT_TRIANGLE));
  st.stopped = true;
  m.apply(st, ev, 1, 20 * MS, nullptr);
  TEST_ASSERT_TRUE(m.report().button(OUT_TRIANGLE));
}

void test_paused_releases_everything() {
  PadMapper m = mapper();
  FakeState st;
  st.run = 1;
  st.aiming = true;
  m.apply(st, nullptr, 0, 0, nullptr);
  m.set_mode(MODE_PAUSED, 10 * MS);
  m.apply(st, nullptr, 0, 50 * MS, nullptr);
  TEST_ASSERT_TRUE(m.report() == PadReport());
  TEST_ASSERT_FALSE(m.set_mode(MODE_PAUSED + 5, 60 * MS));  // unknown mode refused
}

int main(int, char**) {
  UNITY_BEGIN();
  RUN_TEST(test_parse_gta5);
  RUN_TEST(test_params_apply_to_belt);
  RUN_TEST(test_rejects_corruption);
  RUN_TEST(test_jump_press_lasts_30_ms);
  RUN_TEST(test_mash_respects_release_and_cap);
  RUN_TEST(test_run_and_lean_drive_left_stick);
  RUN_TEST(test_sprint_taps_cross_only_when_sprinting);
  RUN_TEST(test_aim_holds_l2_shoot_gated);
  RUN_TEST(test_car_mode_neutral_sticks_and_throttle);
  RUN_TEST(test_exit_vehicle_needs_stopped);
  RUN_TEST(test_paused_releases_everything);
  return UNITY_END();
}
